for (const item of items) {
  const candidate = item.json;
  const role = candidate.position || "Software Engineer";
  const skills = candidate.claimed_skills;
  const background = candidate.past_company_type;

  const systemPrompt = `
Role: You are a Senior Technical Interviewer for a ${role} position.
Your goal is to validate the technical depth of a candidate named ${candidate.candidate_name}.

CONTEXT:
The candidate claims expertise in: ${skills}.
However, their background is from: ${background}.

TASK:
Generate 5 advanced technical interview questions (Studi Kasus) to verify if they truly understand the internal workings of the tech stack or just surface-level knowledge.
Focus on troubleshooting scenarios and architectural trade-offs.

IMPORTANT:
- The questions must be challenging but professional.
- Provide the output in INDONESIAN language.
- Keep the output under 1000 characters because it will be sent to Telegram.

OUTPUT FORMAT (Markdown):
1. Topik: [Nama Topik]
   - Pertanyaan: [Studi Kasus Spesifik]
   - Ekspektasi Jawaban Senior: [Poin Kunci]
`;

  item.json.llm_prompt = systemPrompt;
}

return items;

const aiQuestion = $('Generate Pertanyaan').item.json.text;
const candidateName = $('Loop Over Items').item.json.candidate_name;

let mockAnswer = "";

if (candidateName.includes("Budi")) {
  mockAnswer = "Untuk masalah CrashLoopBackOff, saya akan cek logs pod pakai kubectl logs, lalu describe pod untuk lihat events. Saya akan menganalisis root cause, memeriksa ConfigMap dan Secret, memeriksa resource limits, dan memastikan readiness probe berjalan dengan benar. Setelah root cause ditemukan, saya akan memperbaiki konfigurasi, melakukan testing di staging, lalu deploy ulang dengan monitoring ketat.";
} else {
  mockAnswer = "Saya biasanya restart servernya pak. Kalau masih error saya install ulang Kubernetesnya.";
}

return [
  {
    json: {
      question: aiQuestion,
      candidate_answer: mockAnswer,
      candidate_name: candidateName
    }
  }
];

const data = items[0].json;

const prompt = `
ROLE: You are a Senior Hiring Manager.
TASK: Evaluate the candidate's answer based on the technical question provided.

DATA:
- Candidate Name: ${data.candidate_name}
- Question Given: "${data.question.substring(0, 200)}..." (Truncated for brevity)
- Candidate Answer: "${data.candidate_answer}"

INSTRUCTION:
Give a score (0-100) and a brief critique.
- If the answer shows deep troubleshooting steps (logs, events, root cause analysis), give HIGH score (80-100).
- If the answer is generic (restart server, reinstall), give LOW score (0-40).

OUTPUT FORMAT (Indonesian):
Penilaian untuk ${data.candidate_name}
--------------------------
Skor: [0-100]
Analisa: [Penjelasan singkat 1 kalimat]
Keputusan: [LOLOS / GAGAL]
`;

return [
  {
    json: {
      eval_prompt: prompt
    }
  }
];
